// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {keepMyEther} from "../src/keepMyEther.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    keepMyEther c;

    function setUp() public {
        c = new keepMyEther();
    }

    function _run(address payer, uint256 amount) internal {
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= amount);
        uint256 beforeBal;
        try c.balances(payer) returns (uint256 __r) { beforeBal = __r; } catch { return; }
        try c.withdraw() {} catch { return; }
        assertTrue(c.balances(payer) == 0);
    }

    function testFuzz_run(address payer, uint256 amount) public {
        vm.assume(payer.code.length == 0 && uint160(payer) > 0xffff && payer != address(this) && payer != address(c) && payer != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && payer != 0x000000000000000000636F6e736F6c652e6c6f67 && payer != 0x4e59b44847b379578588920cA78FbF26c0B4956C && payer != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _run(payer, amount);
    }

    receive() external payable {}
}
